-- State transitions declared for MaterialRequest (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION buying.material_requests_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('draft', 'submitted'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: material_requests.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS material_requests_status_transition_check ON buying.material_requests;
CREATE TRIGGER material_requests_status_transition_check
    BEFORE UPDATE OF "status" ON buying.material_requests
    FOR EACH ROW EXECUTE FUNCTION buying.material_requests_status_transition_check();
